/**
 * Generates the WAV fixtures Chromium replays as a fake microphone
 * (--use-file-for-fake-audio-capture). Deterministic, so the committed files
 * can be regenerated byte-identically:
 *
 *   node apps/web/e2e/fixtures/generate.mjs
 */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));

const SAMPLE_RATE = 44100;
const SECONDS = 6;
const A4 = 440;

/** Equal-temperament frequency for a MIDI note. */
const freq = (midi) => A4 * Math.pow(2, (midi - 69) / 12);
/** Detune by cents. */
const detune = (hz, cents) => hz * Math.pow(2, cents / 1200);

/**
 * A plucked-string-ish tone: a few harmonics, mild decay, looping cleanly so
 * Chromium can repeat the file without a click at the seam.
 */
function tone(frequency, seconds = SECONDS) {
  const length = Math.floor(SAMPLE_RATE * seconds);
  const out = new Float32Array(length);
  const weights = [1, 0.5, 0.32, 0.18, 0.1];

  weights.forEach((weight, index) => {
    const harmonic = (index + 1) * frequency;
    if (harmonic >= SAMPLE_RATE / 2) return;
    const step = (2 * Math.PI * harmonic) / SAMPLE_RATE;
    for (let i = 0; i < length; i += 1) out[i] += weight * Math.sin(step * i);
  });

  let peak = 0;
  for (let i = 0; i < length; i += 1) peak = Math.max(peak, Math.abs(out[i]));
  for (let i = 0; i < length; i += 1) out[i] = (out[i] / peak) * 0.7;
  return out;
}

/** Linear-in-pitch sweep, for the User Story 2 retune spec. */
function sweep(fromHz, toHz, seconds = SECONDS) {
  const length = Math.floor(SAMPLE_RATE * seconds);
  const out = new Float32Array(length);
  let phase = 0;
  for (let i = 0; i < length; i += 1) {
    const t = i / (length - 1);
    const f = fromHz * Math.pow(toHz / fromHz, t);
    phase += (2 * Math.PI * f) / SAMPLE_RATE;
    out[i] = 0.7 * Math.sin(phase);
  }
  return out;
}

function writeWav(name, samples) {
  const dataLength = samples.length * 2;
  const buffer = Buffer.alloc(44 + dataLength);

  buffer.write('RIFF', 0);
  buffer.writeUInt32LE(36 + dataLength, 4);
  buffer.write('WAVE', 8);
  buffer.write('fmt ', 12);
  buffer.writeUInt32LE(16, 16); // PCM chunk size
  buffer.writeUInt16LE(1, 20); // PCM
  buffer.writeUInt16LE(1, 22); // mono
  buffer.writeUInt32LE(SAMPLE_RATE, 24);
  buffer.writeUInt32LE(SAMPLE_RATE * 2, 28); // byte rate
  buffer.writeUInt16LE(2, 32); // block align
  buffer.writeUInt16LE(16, 34); // bits per sample
  buffer.write('data', 36);
  buffer.writeUInt32LE(dataLength, 40);

  for (let i = 0; i < samples.length; i += 1) {
    const clamped = Math.max(-1, Math.min(1, samples[i]));
    buffer.writeInt16LE(Math.round(clamped * 32767), 44 + i * 2);
  }

  writeFileSync(join(HERE, name), buffer);
  console.log(`wrote ${name} (${(buffer.length / 1024).toFixed(0)} KB)`);
}

/**
 * A tone that stops, for the US2 marker-rest spec.
 *
 * Chromium loops the fixture, so the silence has to live INSIDE the file: the
 * marker must be observed resting during the quiet stretch and tracking again
 * when the tone comes back round. The silent half is 3 s — far past the filter
 * chain's 400 ms hold, with room for the e2e sampling window on top.
 */
function toneThenSilence(frequency, toneSeconds = 3, silentSeconds = 3) {
  const sounding = tone(frequency, toneSeconds);
  const out = new Float32Array(sounding.length + Math.floor(SAMPLE_RATE * silentSeconds));
  out.set(sounding, 0);
  return out;
}

const e2 = freq(40); // 82.41 Hz, guitar low E
writeWav('e2-in-tune.wav', tone(e2));
writeWav('e2-flat-20.wav', tone(detune(e2, -20)));
writeWav('e2-sharp-20.wav', tone(detune(e2, 20)));
writeWav('e2-to-d2-sweep.wav', sweep(e2, freq(38)));
writeWav('e2-then-silence.wav', toneThenSilence(detune(e2, -20)));

/**
 * 007 — notes chosen for their ANGLE on the dial, not for the guitar.
 *
 * The existing fixtures are all E2, which is pitch class 4 and therefore 120
 * degrees. One angle cannot distinguish a correct dial from a mirrored one, or
 * from one that ignores pitch class altogether, so these spread four more
 * classes around the circle: C at the top, D at 60, A at 270 (the assertion
 * that catches a mirror, since it becomes 90), and B just below the top.
 */
const c4 = freq(60); // 261.63 Hz — pitch class 0, straight up
const d3 = freq(50); // 146.83 Hz — pitch class 2, 60 degrees
const a4 = freq(69); // 440 Hz — pitch class 9, 270 degrees
const b3 = freq(59); // 246.94 Hz — pitch class 11, 330 degrees

writeWav('c4-in-tune.wav', tone(c4));
writeWav('d3-in-tune.wav', tone(d3));
writeWav('d3-sharp-25.wav', tone(detune(d3, 25)));
writeWav('d3-flat-25.wav', tone(detune(d3, -25)));
writeWav('a4-in-tune.wav', tone(a4));

/**
 * The crossing at twelve o'clock, for G10.
 *
 * B3 30 cents flat up to C4 30 cents sharp: the needle travels 321 -> 345 ->
 * 369 degrees, passing the ONE boundary where the raw angle jumps by a full
 * turn (B +50 is 345, C -50 is -15). Every other boundary is continuous in the
 * raw value and cannot catch a missing unwrap.
 */
writeWav('b3-to-c4-sweep.wav', sweep(detune(b3, -30), detune(c4, 30)));

/**
 * Nothing at all, for FR-163.
 *
 * "No needle before the first reading of a session" is a state with no angle
 * rather than an angle of zero, and it is the one state the other fixtures
 * cannot produce: every one of them starts sounding immediately, and Chromium
 * loops them, so a reading has always already happened.
 */
writeWav('silence.wav', new Float32Array(Math.floor(SAMPLE_RATE * SECONDS)));
